:root {
  --bg-card: #0d1b2a;
  --bg-header: #112240;
  --bg-stats: #0a1628;
  --bg-track: #1e3a5f;
  --accent-blue: #4fc3f7;
  --accent-green: #00e5a0;
  --accent-alert: #ff6b35;
  --text-primary: #e8f4fd;
  --text-secondary: #7fb3d3;
  --text-muted: #4a7fa5;
  --crew-bg: #1e3a5f;
  --tag-bg: #1a3050;
  --tag-alert-bg: #3d1a0d;
  --tag-alert-text: #ff6b35;
  --border-color: #1e3a5f;
  --btn-bg: #4fc3f7;
  --btn-text: #0d1b2a;
}

.mission-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  width: 520px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-color);
}

.mission-status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-green);
}

.status-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--accent-green);
}

.mission-id {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.card-body {
  display: flex;
  gap: 0;
  padding: 16px;
  align-items: flex-start;
}

.mission-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 16px;
  border-right: 1px solid var(--border-color);
}

.mission-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.mission-desc {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.5;
}

.crew-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.crew-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.crew-badges {
  display: flex;
  gap: 4px;
}

.crew-badge {
  background: var(--crew-bg);
  color: var(--accent-blue);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.5px;
  border: 1px solid var(--accent-blue);
}

.stats-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-left: 16px;
  min-width: 110px;
}

.stat-block {
  background: var(--bg-stats);
  border-radius: 8px;
  padding: 6px 10px;
  display: flex;
  align-items: baseline;
  gap: 3px;
  flex-wrap: wrap;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--accent-blue);
  line-height: 1;
}

.stat-unit {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.stat-key {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--text-muted);
  width: 100%;
  margin-top: 2px;
}

.progress-bar-wrap {
  padding: 0 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.progress-bar-track {
  width: 100%;
  height: 6px;
  background: var(--bg-track);
  border-radius: 99px;
  overflow: hidden;
}

.progress-bar-fill {
  width: 83%;
  height: 100%;
  background: var(--accent-blue);
  border-radius: 99px;
}

.progress-labels {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.5px;
}

.card-footer {
  background: var(--bg-header);
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  gap: 10px;
}

.tag-row {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.tag {
  background: var(--tag-bg);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 99px;
  letter-spacing: 0.3px;
}

.tag-alert {
  background: var(--tag-alert-bg);
  color: var(--tag-alert-text);
}

.telemetry-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 7px;
  padding: 7px 14px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  letter-spacing: 0.3px;
}
